for key,value in {'VERSION':html.escape(version),'GALLERY':gallery,'EXTRAS':extras,'GO':validation['go_race']['passed'],'SKIP':validation['go_race']['skipped'],'NODE':validation['node_tests'],'BROWSER':validation['fixture_browser_scenarios'],'ABI':len(probe['checks']),'BINARY':binary_hash}.items():page=page.replace('@@'+key+'@@',str(value))
assert '@@' not in page
file=out/'WorkBuddy-交付说明.html';file.write_text(page,encoding='utf-8')
(out/'DELIVERY-META.json').write_text(json.dumps({'version':version,'html':file.name,'html_sha256':h(file.read_bytes()),'binary_sha256':binary_hash,'screenshots':capture,'binary_probe':probe,'official_frontend':validation.get('official_frontend',{})},ensure_ascii=False,indent=2)+'\n')
print(file)
